:root {
  /* Colors */
  --color-linen-canvas: #fffefc;
  --color-mint-wash: #e1f4df;
  --color-sprout-tint: #cfe7d3;
  --color-sage-field: #b1dbb8;
  --color-mist-panel: #b6ced5;
  --color-graphite-nav: #222222;
  --color-forest-ink: #0f3e17;
  --color-paper-label: #ffffff;

  /* Typography — Font Families */
  --font-faire-octave: "Faire Octave", "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-suisseintl: "Suisseintl", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 18px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 23px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 25px;
  --leading-subheading: 1.35;
  --tracking-subheading: -0.25px;
  --text-heading-sm: 28px;
  --leading-heading-sm: 1.3;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1.35;
  --tracking-heading: -0.4px;
  --text-heading-lg: 56px;
  --leading-heading-lg: 1.2;
  --tracking-heading-lg: -1.7px;
  --text-display: 74px;
  --leading-display: 1.05;
  --tracking-display: -2.2px;
  --leading-none: 1;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-7: 7px;
  --spacing-9: 9px;
  --spacing-11: 11px;
  --spacing-14: 14px;
  --spacing-18: 18px;
  --spacing-21: 21px;
  --spacing-28: 28px;
  --spacing-35: 35px;
  --spacing-42: 42px;
  --spacing-56: 56px;
  --spacing-70: 70px;
  --spacing-84: 84px;
  --spacing-98: 98px;
  --spacing-140: 140px;

  /* Layout */
  --layout-page-max-width: 1450px;
  --layout-content-width: 1042px;
  --layout-text-width: 901px;
  --layout-section-gap: 140px;
  --layout-section-gap-mobile: 70px;
  --layout-card-padding: 42px;
  --layout-element-gap: 21px;

  /* Border Radius */
  --radius-sm: 7px;
  --radius-md: 14px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-cards: 14px;
  --radius-buttons: 14px;
  --radius-images: 14px;
  --radius-tags: 7px;
  --radius-pills: 999px;
  --radius-nav: 0px;
  --radius-sections: 0px;

  /* Shadows */
  /* none: the system is shadowless; elevation is tonal */

  /* Surfaces */
  --surface-linen-canvas: #fffefc;
  --surface-mint-wash: #e1f4df;
  --surface-sage-field: #b1dbb8;
  --surface-mist-panel: #b6ced5;
  --surface-forest-ink: #0f3e17;
}

